import{describe,it,expect}from"vitest";describe("Service Worker Strategy Unit Tests",()=>{const e=["/","/index.html","/styles.css","/app.js","/data.js"];it("defines cache name and core static assets",()=>{expect("ii-explorer-v1").toBe("ii-explorer-v1"),expect(e).toContain("/index.html"),expect(e).toContain("/styles.css")}),it("matches static asset URLs for cache strategy",()=>{const e=e=>e.endsWith(".css")||e.endsWith(".js")||e.endsWith(".html")||e.endsWith(".png");expect(e("/styles.css")).toBe(!0),expect(e("/data.js")).toBe(!0),expect(e("/frontend/api/dynamic")).toBe(!1)}),it("handles offline fallback response decision",()=>{const t=(t,s)=>t?{status:200,source:"network"}:e.includes(s)?{status:200,source:"cache"}:{status:503,source:"offline-fallback"};expect(t(!0,"/index.html")).toEqual({status:200,source:"network"}),expect(t(!1,"/index.html")).toEqual({status:200,source:"cache"}),expect(t(!1,"/unknown")).toEqual({status:503,source:"offline-fallback"})})});